'use client';

import { useCallback, useId, useRef, type CSSProperties, type JSX, type ReactNode } from 'react';
import {
  Dialog as RACDialog,
  Heading,
  Modal,
  ModalOverlay,
  PopoverContext,
  useSlottedContext,
  type DialogProps as RACDialogProps,
} from 'react-aria-components';
import { IconX } from '@tabler/icons-react';
import { Button } from './button';
import styles from './dialog.module.css';

export { DialogTrigger, type DialogTriggerProps } from 'react-aria-components';

const cx = (...c: Array<string | false | null | undefined>) => c.filter(Boolean).join(' ');

/**
 * Overlays portal to <body>, outside any ThemeScope, so scoped tokens would not reach them. At open time we
 * copy the scope's data-strata-* attributes (and dir/lang) from the element the overlay belongs to onto the
 * overlay root, which makes the root a scope of its own. Nested overlays find the attributes on their parent.
 */
const SCOPE_ATTRS = ['data-strata-theme', 'data-strata-scheme', 'data-strata-density'] as const;
function mirrorScope(overlay: HTMLElement, source: Element | null | undefined): void {
  if (!source || overlay.contains(source)) return;
  for (const name of SCOPE_ATTRS) {
    // Look each attribute up on its own: a single-tenant app themes :root and scopes only the scheme.
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
  for (const name of ['dir', 'lang']) {
    const value = source.closest(`[${name}]`)?.getAttribute(name);
    if (value) overlay.setAttribute(name, value);
  }
}

export interface DialogRenderProps {
  /** Closes the dialog. */
  close: () => void;
}

export interface DialogProps extends Omit<RACDialogProps, 'children' | 'className' | 'style'> {
  /** Heading at the top of the dialog; also its accessible name. */
  title: ReactNode;
  /** Supporting text under the title, announced with it. */
  description?: ReactNode;
  /** Body content, or a function that receives `{ close }`. Scrolls when taller than the viewport allows. */
  children?: ReactNode | ((opts: DialogRenderProps) => ReactNode);
  /** Actions pinned to the bottom, usually Buttons. Also accepts a function that receives `{ close }`. */
  footer?: ReactNode | ((opts: DialogRenderProps) => ReactNode);
  /** Maximum width. */
  size?: 'sm' | 'md' | 'lg';
  /** Whether clicking the backdrop closes the dialog. Escape always closes unless `isKeyboardDismissDisabled`. */
  isDismissable?: boolean;
  /** Whether Escape is ignored. */
  isKeyboardDismissDisabled?: boolean;
  /** Controlled open state — only when the dialog is not inside a DialogTrigger. */
  isOpen?: boolean;
  /** Initial open state — only when the dialog is not inside a DialogTrigger. */
  defaultOpen?: boolean;
  /** Called when the open state changes — only when the dialog is not inside a DialogTrigger. */
  onOpenChange?: (isOpen: boolean) => void;
  /** Class for the dialog panel. */
  className?: string;
  /** Style for the dialog panel. */
  style?: CSSProperties;
}

/**
 * A modal window with a title, optional description, scrollable body and footer actions. Use inside a
 * DialogTrigger, or control it with `isOpen`/`onOpenChange`. Alert dialogs (`role="alertdialog"`) never show
 * the close button — the user must choose an action.
 */
export function Dialog({
  title,
  description,
  children,
  footer,
  size = 'md',
  isDismissable = true,
  isKeyboardDismissDisabled,
  isOpen,
  defaultOpen,
  onOpenChange,
  className,
  style,
  role,
  ...props
}: DialogProps): JSX.Element {
  const descriptionId = useId();
  const triggerRef = useSlottedContext(PopoverContext)?.triggerRef;
  const anchorRef = useRef<HTMLSpanElement>(null);
  const overlayRef = useCallback(
    (node: HTMLDivElement | null) => {
      if (node) mirrorScope(node, triggerRef?.current ?? anchorRef.current ?? document.activeElement);
    },
    [triggerRef],
  );
  const isAlert = role === 'alertdialog';

  return (
    <>
      {/* Controlled dialogs have no trigger to read the ThemeScope from, so leave an invisible marker. */}
      {!triggerRef && <span ref={anchorRef} hidden />}
      <ModalOverlay
        ref={overlayRef}
        className={styles.overlay}
        isDismissable={isDismissable && !isAlert}
        isKeyboardDismissDisabled={isKeyboardDismissDisabled}
        isOpen={isOpen}
        defaultOpen={defaultOpen}
        onOpenChange={onOpenChange}
      >
        <Modal className={cx(styles.panel, className)} style={style} data-size={size}>
          <RACDialog
            {...props}
            role={role}
            aria-describedby={cx(description != null && descriptionId, props['aria-describedby']) || undefined}
            className={styles.dialog}
          >
            {({ close }) => (
              <>
                <header className={styles.header}>
                  <Heading slot="title" level={2} className={styles.title}>
                    {title}
                  </Heading>
                  {description != null && (
                    <p id={descriptionId} className={styles.description}>
                      {description}
                    </p>
                  )}
                </header>
                {children != null && (
                  <div className={styles.body}>{typeof children === 'function' ? children({ close }) : children}</div>
                )}
                {footer != null && (
                  <footer className={styles.footer}>{typeof footer === 'function' ? footer({ close }) : footer}</footer>
                )}
                {!isAlert && (
                  <Button variant="ghost" size="icon" aria-label="Close" onPress={close} className={styles.close}>
                    <IconX aria-hidden stroke={1.75} />
                  </Button>
                )}
              </>
            )}
          </RACDialog>
        </Modal>
      </ModalOverlay>
    </>
  );
}

/* Backdrop. Portalled to <body>, so it re-applies the ThemeScope base (font, colour, box model). */
.overlay {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  box-sizing: border-box;
  container-type: inline-size;
  /* Dim what's behind by a fixed amount. A colour tint can't do this in both schemes: every surface token is
     already near the page colour in dark schemes, and light-dark() gets mangled by Lightning CSS pipelines. */
  -webkit-backdrop-filter: brightness(0.55);
  backdrop-filter: brightness(0.55);
  font-family: var(--strata-font-body);
  font-size: var(--strata-font-size-md);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-default);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}
.overlay *,
.overlay *::before,
.overlay *::after {
  box-sizing: border-box;
}

.panel {
  --dialog-inline-size: calc(var(--strata-space-16) * 8);
  position: relative;
  display: flex;
  flex-direction: column;
  inline-size: calc(100% - var(--strata-space-4) * 2);
  max-inline-size: var(--dialog-inline-size);
  max-block-size: min(85dvh, calc(100% - var(--strata-space-4) * 2));
  margin: auto;
  background: var(--strata-color-surface-raised);
  border: 1px solid var(--strata-color-border-default);
  border-radius: var(--strata-radius-container);
  box-shadow: var(--strata-shadow-overlay);
  outline: none;
}
.panel[data-size='sm'] {
  --dialog-inline-size: calc(var(--strata-space-16) * 6);
}
.panel[data-size='lg'] {
  --dialog-inline-size: calc(var(--strata-space-16) * 10);
}

.dialog {
  display: flex;
  flex-direction: column;
  flex: 1 1 auto;
  gap: var(--strata-space-4);
  min-block-size: 0;
  padding-block: var(--strata-card-inset);
  outline: none;
}
/* Programmatic focus on open. Pseudo-class selector so page-level `[tabindex]:focus-visible` rules can't outrank it. */
.dialog:focus-visible {
  outline: none;
}

.header {
  display: grid;
  gap: var(--strata-space-1);
  padding-inline: var(--strata-card-inset);
  /* Leave room for the close button. */
  padding-inline-end: calc(var(--strata-card-inset) + var(--strata-control-height));
}
.dialog[role='alertdialog'] .header {
  padding-inline-end: var(--strata-card-inset);
}
.title {
  margin: 0;
  font-family: var(--strata-font-heading);
  font-size: var(--strata-font-size-lg);
  font-weight: var(--strata-font-weight-semibold);
  line-height: var(--strata-line-height-snug);
  letter-spacing: var(--strata-font-heading-tracking);
  color: var(--strata-color-text-default);
}
.description {
  margin: 0;
  font-size: var(--strata-font-size-sm);
  line-height: var(--strata-line-height-normal);
  color: var(--strata-color-text-subtle);
}

/* The body scrolls; header and footer stay put. Block padding keeps focus rings of edge fields visible. */
.body {
  display: grid;
  align-content: start;
  gap: var(--strata-field-gap);
  flex: 1 1 auto;
  min-block-size: 0;
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: var(--strata-space-1) var(--strata-card-inset);
  margin-block: calc(var(--strata-space-1) * -1);
}

.footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: flex-end;
  gap: var(--strata-space-2);
  padding-inline: var(--strata-card-inset);
}

.close {
  position: absolute;
  inset-block-start: calc(var(--strata-card-inset) - var(--strata-space-2));
  inset-inline-end: calc(var(--strata-card-inset) - var(--strata-space-2));
  color: var(--strata-color-text-subtle);
}

/* Narrow viewports: a full-width panel anchored to the bottom edge, actions stacked. */
@container (inline-size < 480px) {
  .panel {
    inline-size: 100%;
    max-inline-size: none;
    margin: auto 0 0;
    border-inline: 0;
    border-block-end: 0;
    border-end-start-radius: 0;
    border-end-end-radius: 0;
    padding-block-end: env(safe-area-inset-bottom, 0);
  }
  .footer {
    flex-direction: column-reverse;
    align-items: stretch;
  }
}

@media (prefers-reduced-motion: no-preference) {
  .overlay[data-entering] {
    animation: fade var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
  .overlay[data-exiting] {
    animation: fade var(--strata-motion-duration-fast) var(--strata-motion-easing) reverse;
  }
  .panel[data-entering] {
    animation: zoom var(--strata-motion-duration-normal) var(--strata-motion-easing);
  }
  .panel[data-exiting] {
    animation: zoom var(--strata-motion-duration-fast) var(--strata-motion-easing) reverse;
  }
  @container (inline-size < 480px) {
    .panel[data-entering] {
      animation-name: rise;
    }
    .panel[data-exiting] {
      animation-name: rise;
    }
  }
}

@keyframes fade {
  from {
    opacity: 0;
  }
}
@keyframes zoom {
  from {
    opacity: 0;
    scale: 0.97;
  }
}
@keyframes rise {
  from {
    translate: 0 100%;
  }
}
